/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            if (fnAKCKwdSearchCodeType(((document.searchForm || { elements: [] }).comAbbrv))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnTabView
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx
 * @returns
 * @hidden N
*/
scwin.fnTabView = async function (idx) {
    /* sdd-asis-lifecycle:begin fnTabView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $(document).find("li[id=tabView]").each(function(index) {
            if (idx === index) {
                if (!$(this).hasClass("active")) {
                    $(this).addClass("active");
                }
            } else {
                if ($(this).hasClass("active")) {
                    $(this).removeClass("active");
                }
            }
    });
    if (idx === "0") {
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("method", "loadPageForDisclsAnalysisChart");
    } else {
        if (idx === "1") {
            $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("method", "loadPageForIdxComparisonChart");
        } else {
            if (idx === "2") {
                $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("method", "loadPageForIssueComparisonChart");
            }
        }
    }
    await scwin.fnSearchDisclsChartInfo();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getRecentCompanyFromCookie
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getRecentCompanyFromCookie = function () {
    /* sdd-asis-lifecycle:begin getRecentCompanyFromCookie — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const cookies = scwin.fnGetCookie('krxComp');
    const item = null;
    let userCompaniesArray = null;
    var tmpstr = null;
    if (cookies != null) {
        userCompaniesArray = cookies.split("/");
    }
    const issues = "";
    var tmpstr = "";
    if (userCompaniesArray != null && userCompaniesArray !== "") {
        tmpstr = userCompaniesArray[0].split(",");
    }
    return tmpstr[2];
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnGetCookie
 * @author Inswave
 * @date 2026. 09. 29
 * @param keyname
 * @returns
 * @hidden N
*/
scwin.fnGetCookie = function (keyname) { const v = $c.util.getSessionStorage(keyname); return (v === undefined || v === null) ? '' : v; };


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let comAbbrv = $c.util.getComponent('ipt_comAbbrv').getValue(); if (comAbbrv == null) { comAbbrv = ''; }
    if (comAbbrv == null || comAbbrv === "") {
        await $c.win.alert("회사명을 입력해 주세요.");
        return;
    }
    $c.util.getComponent("tabContents").setStyle("display", "");
    console.error("[sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    await scwin.fnSearchPresentPrice();
    await scwin.fnSearchDisclsChartInfo();
    scwin.closeSearchAutoCompleteDiv();
    /* sdd-asis-lifecycle:end */
};


