/**
 * @method
 * @name scwin.fnSearchCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpName = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", "");
    let val = $c.util.getComponent('ipt_comAbbrv').getValue(); if (val == null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("searchCorpName", val);
        console.warn('[sdd] 미실현(재설계 분류 #128): fnAKCKwdSearchCorpName(' + "" + ')');
    } else {
        await scwin.fnSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpNameAllCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    /* sdd-asis-lifecycle:begin fnSearchCorpNameAllCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", "");
    if (items.length == 1) {
        await scwin.fnSearchCorpCode(items[0]);
    } else {
        if (items.length > 1) {
            scwin.fnCommFindCorpName();
        } else {
            await scwin.fnSearchCorpCode(null);
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpCode = async function (items) {
    /* sdd-asis-lifecycle:begin fnSearchCorpCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (items == null) {
        const val = ($c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", '');
        $c.util.getComponent('ipt_comAbbrv').setValue('');
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
    } else {
        const comabbr = $c.util.getComponent('ipt_comAbbrv');
        const isurcd = items.isurcd;
        const repisucd = $c.util.getComponent('ipt_repIsuCd');
        const repisusrtkornm = items.repisusrtkornm;
        const spotisutrdmkttpcd = items.spotisutrdmkttpcd;
        const liststatcd = items.liststatcd;
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comabbr);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisusrtkornm);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comabbr);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisusrtkornm);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", spotisutrdmkttpcd);
        if (spotisutrdmkttpcd === "1") {
            $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "stock");
        } else {
            if (spotisutrdmkttpcd === "2") {
                $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "kosdaq");
            } else {
                if (spotisutrdmkttpcd === "6") {
                    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "konex");
                }
            }
        }
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", spotisutrdmkttpcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("repIsuCd", repisucd);
        $c.util.getComponent('ipt_comAbbrv').setValue(comabbr);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("liststatcd", liststatcd);
        await scwin.fnSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnCommFindCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
